const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '比例尺 1:25000' },
      { kind: 'text', payload: '图上距离 6 厘米' },
      { kind: 'text', payload: '实际距离 150000 厘米' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: '3' },
      { kind: 'text', payload: '4' },
      { kind: 'text', payload: '5' },
      { kind: 'text', payload: '6 厘米' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = W * 0.10;
    var x1 = W * 0.90;
    var y = H * 0.50;
    var tickLen = Math.max(14, Math.min(28, H * 0.045));
    var titleY = H * 0.14;
    var subtitleY = H * 0.24;
    var tickLabelY = y + tickLen / 2 + 20;
    var actualY = H * 0.84;
    var base = [['M', x0, y], ['L', x1, y]];
    var ticks = [];
    var tickAnchors = [];
    for (var i = 0; i <= 6; i++) {
      var xi = x0 + (x1 - x0) * i / 6;
      ticks.push(['M', xi, y - tickLen / 2], ['L', xi, y + tickLen / 2]);
      tickAnchors.push(xi);
    }
    var children = [
      { type: 'path', pathId: 'base', fill: '#26354a', stroke: { width: 4 } },
      { type: 'path', pathId: 'ticks', fill: '#26354a', stroke: { width: 2 } },
      { type: 'label', contentId: metrics[0].contentId, anchor: { x: W / 2, y: titleY }, hAlign: 'center', vAlign: 'middle', color: '#26354a' },
      { type: 'label', contentId: metrics[1].contentId, anchor: { x: W / 2, y: subtitleY }, hAlign: 'center', vAlign: 'middle', color: '#26354a' },
      { type: 'label', contentId: metrics[2].contentId, anchor: { x: W / 2, y: actualY }, hAlign: 'center', vAlign: 'middle', color: '#26354a' }
    ];
    for (var j = 0; j <= 6; j++) {
      children.push({ type: 'label', contentId: metrics[3 + j].contentId, anchor: { x: tickAnchors[j], y: tickLabelY }, hAlign: 'center', vAlign: 'top', color: '#26354a' });
    }
    return {
      schemaVersion: 1,
      sceneId: 'scale-line',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'base', commands: base },
        { id: 'ticks', commands: ticks }
      ],
      root: { type: 'group', children: children }
    };
  }
};
